import{_ as t,c as o,o as i,aj as n}from"./chunks/framework.CDhdelVI.js";const c=JSON.parse('{"title":"Fermentation","description":"Practical fermentation workflow for dough: timing, temperature, signs of readiness, and common fixes.","frontmatter":{"title":"Fermentation","description":"Practical fermentation workflow for dough: timing, temperature, signs of readiness, and common fixes.","head":[["meta",{"name":"description","content":"Practical fermentation workflow for dough: timing, temperature, signs of readiness, and common fixes."}],["meta",{"property":"og:title","content":"Fermentation"}],["meta",{"property":"og:description","content":"Practical fermentation workflow for dough: timing, temperature, signs of readiness, and common fixes."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/fermentation.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Fermentation"}],["meta",{"name":"twitter:description","content":"Practical fermentation workflow for dough: timing, temperature, signs of readiness, and common fixes."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/fermentation.html"}]]},"headers":[],"relativePath":"guides/fermentation.md","filePath":"guides/fermentation.md"}'),a={name:"guides/fermentation.md"};function r(l,e,s,d,m,g){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="fermentation" tabindex="-1">Fermentation <a class="header-anchor" href="#fermentation" aria-label="Permalink to “Fermentation”">​</a></h1><p>Fermentation is the engine of dough development. Yeast makes gas, enzymes keep working, and time changes flavor and structure.</p><h2 id="what-fermentation-is-doing" tabindex="-1">What Fermentation Is Doing <a class="header-anchor" href="#what-fermentation-is-doing" aria-label="Permalink to “What Fermentation Is Doing”">​</a></h2><ul><li>Producing CO2 for rise</li><li>Building acidity and aroma</li><li>Improving extensibility over time</li><li>Changing dough strength as gluten relaxes and reorganizes</li></ul><h2 id="basic-workflow" tabindex="-1">Basic Workflow <a class="header-anchor" href="#basic-workflow" aria-label="Permalink to “Basic Workflow”">​</a></h2><ol><li>Mix dough until evenly hydrated.</li><li>Ferment in bulk (room or cold, depending on style).</li><li>Add folds early if dough needs strength.</li><li>Stop bulk when dough is visibly aerated and alive, not collapsed.</li></ol><h2 id="bulk-fermentation-cues-use-these-not-the-clock-alone" tabindex="-1">Bulk Fermentation Cues (Use These, Not the Clock Alone) <a class="header-anchor" href="#bulk-fermentation-cues-use-these-not-the-clock-alone" aria-label="Permalink to “Bulk Fermentation Cues (Use These, Not the Clock Alone)”">​</a></h2><ul><li><strong>Volume</strong>: usually 50-100% expansion, style-dependent</li><li><strong>Surface</strong>: smoother, slightly domed, small bubbles visible</li><li><strong>Feel</strong>: lighter and gassy, not dense and tight</li><li><strong>Edges in container</strong>: small gas pockets along the sides</li></ul><h2 id="room-vs-cold-fermentation" tabindex="-1">Room vs Cold Fermentation <a class="header-anchor" href="#room-vs-cold-fermentation" aria-label="Permalink to “Room vs Cold Fermentation”">​</a></h2><ul><li><strong>Room fermentation</strong> moves faster and needs tighter timing.</li><li><strong>Cold fermentation</strong> moves slower and gives wider timing tolerance plus deeper flavor.</li></ul><h3 id="cold-fermentation-baseline" tabindex="-1">Cold Fermentation Baseline <a class="header-anchor" href="#cold-fermentation-baseline" aria-label="Permalink to “Cold Fermentation Baseline”">​</a></h3><ul><li>Refrigerate dough <strong>12-48 hours</strong> as a practical starting range.</li><li>Keep dough covered to prevent surface drying.</li><li>Expect final proofing to move more slowly after cold storage.</li></ul><p>If your dough keeps overshooting, lower yeast or go colder.<br> If it keeps lagging, increase temperature or give more time.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to “Common Mistakes”">​</a></h2><ul><li>Waiting for an exact clock time and ignoring dough signals</li><li>Over-warming dough early and losing control later</li><li>Adding too much bench flour instead of using folds/time</li><li>Letting bulk run until dough weakens and collapses</li></ul><h2 id="quick-fixes" tabindex="-1">Quick Fixes <a class="header-anchor" href="#quick-fixes" aria-label="Permalink to “Quick Fixes”">​</a></h2><ul><li><strong>Dough too slow</strong>: warmer spot, longer rest, or slightly more yeast next batch</li><li><strong>Dough too fast</strong>: cooler spot, shorter bulk, or slightly less yeast next batch</li><li><strong>Dough tight after bulk</strong>: longer bench rest before shaping</li><li><strong>Dough weak after bulk</strong>: end bulk earlier next time or add one more fold cycle</li><li><strong>Sluggish from fridge</strong>: add extra bench time before shaping or baking</li><li><strong>Overproofing during cold storage</strong>: reduce yeast slightly next batch</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/proofing.html">Proofing</a></li><li><a href="/guides/folding.html">Folding</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul>',19)])])}const u=t(a,[["render",r]]);export{c as __pageData,u as default};
